/* auto_fixture_v3.h - frozen automation records with BL-224's fields, still format compat 1
 * (docs/features/41 DESIGN.md section 6 "Stored format" and section 15; AUT-008).
 *
 * Never edit; a later format change adds auto_fixture_v4.h. Written by hand, never generated by
 * the encoder. auto_fixture_v1.h and auto_fixture_v2.h stay as they are and still read the same.
 *
 * BL-224's fields:
 *   0x19       u8   a trouble trigger's trouble (critical): 1 the power, 2 the panel's battery,
 *                   3 a sensor, 4 a siren; absent = any
 *   action kinds    3 a wired output, 5 remind to arm, 6 "still armed", 7 the door chime,
 *                   8 a notification (critical: an older firmware loads them as NEWER)
 *   sub 0xD    u8   an output action's wired output, 1..4 (critical)
 *   sub 0xE    u8   option: a reminder's notification, a chime's on (critical)
 *   0x84       u8   saved_by: who saved it when that isn't made_by (ignorable)
 */
#ifndef AUTO_FIXTURE_V3_H
#define AUTO_FIXTURE_V3_H

#include <stdint.h>

/* (n) 23:00 every day -> Remind to arm partition 1, with a notification. uid 21. */
static const uint8_t AUTO_FX_N[] = {
    0x01,                         /* compat 1 */
    0x01, 0x02, 0x15, 0x00,       /* uid 21 */
    0x10, 0x01, 0x07,             /* trigger: time */
    0x14, 0x02, 0x64, 0x05,       /* minute 1380 (23:00) */
    0x20, 0x01, 0x05,             /* action 1: remind */
    0x2A, 0x01, 0x01,             /* partition 1 */
    0x2E, 0x01, 0x01,             /* option: also a notification */
};

/* (o) Zone 1 opens, 22:00 to 06:00 -> a notification, then output 2 on for 30 minutes. uid 22. */
static const uint8_t AUTO_FX_O[] = {
    0x01,
    0x01, 0x02, 0x16, 0x00,       /* uid 22 */
    0x10, 0x01, 0x05,             /* trigger: zone opened */
    0x13, 0x02, 0x01, 0x00,       /* zone 1 */
    0x16, 0x02, 0x29, 0x05,       /* from 1320 + 1 */
    0x17, 0x02, 0x69, 0x01,       /* to 360 + 1 */
    0x20, 0x01, 0x08,             /* action 1: notify */
    0x30, 0x01, 0x03,             /* action 2: output */
    0x33, 0x01, 0x01,             /* ACT_ON */
    0x38, 0x02, 0x1E, 0x00,       /* off after 30 minutes */
    0x3D, 0x01, 0x02,             /* output 2 */
};

/* (p) The power goes off -> the door chime off on partition 1, made by user 2. uid 23. */
static const uint8_t AUTO_FX_P[] = {
    0x01,
    0x01, 0x02, 0x17, 0x00,       /* uid 23 */
    0x04, 0x01, 0x02,             /* made_by user 2 */
    0x10, 0x01, 0x08,             /* trigger: trouble */
    0x19, 0x01, 0x01,             /* the power */
    0x20, 0x01, 0x07,             /* action 1: chime (option absent: off) */
    0x2A, 0x01, 0x01,             /* partition 1 */
};

/* (q) 16:00 on weekdays -> "still armed" on partition 1. uid 24. */
static const uint8_t AUTO_FX_Q[] = {
    0x01,
    0x01, 0x02, 0x18, 0x00,       /* uid 24 */
    0x10, 0x01, 0x07,             /* trigger: time */
    0x14, 0x02, 0xC0, 0x03,       /* minute 960 (16:00) */
    0x15, 0x01, 0x1F,             /* Monday to Friday */
    0x20, 0x01, 0x06,             /* action 1: still armed */
    0x2A, 0x01, 0x01,             /* partition 1 */
};

/* (r) 23:00 -> Arm Away on partition 1, 5 minutes' warning, set up by the installer (user 1)
 * as the system master (user 2). uid 25. */
static const uint8_t AUTO_FX_R[] = {
    0x01,
    0x01, 0x02, 0x19, 0x00,       /* uid 25 */
    0x04, 0x01, 0x02,             /* made_by user 2 */
    0x10, 0x01, 0x07,             /* trigger: time */
    0x14, 0x02, 0x64, 0x05,       /* minute 1380 */
    0x20, 0x01, 0x02,             /* action 1: arm */
    0x2A, 0x01, 0x01,             /* partition 1 */
    0x2B, 0x01, 0x01,             /* Away */
    0x2C, 0x01, 0x05,             /* 5 minutes */
    0x84, 0x01, 0x01,             /* saved_by user 1 */
};

/* (s) A trouble trigger naming a trouble from later (5): NEWER, never run. */
static const uint8_t AUTO_FX_S[] = {
    0x01,
    0x01, 0x02, 0x1A, 0x00,
    0x10, 0x01, 0x08,
    0x19, 0x01, 0x05,
    0x20, 0x01, 0x08,
};

#endif /* AUTO_FIXTURE_V3_H */
